  <a class="skip-link" href="#main-content">Skip to main content</a>
  <main id="main-content">
    <section class="contact-card" aria-labelledby="support-heading">
      <h1 id="support-heading">Contact support</h1>
      <p class="intro">Share your details and our support team will reach out as soon as possible.</p>

      <form id="support-form" novalidate>
        <div class="form-field">
          <label for="full-name">Full name <span class="required" aria-hidden="true">*</span></label>
          <input
            id="full-name"
            name="fullName"
            type="text"
            autocomplete="name"
            required
            aria-required="true"
            aria-describedby="full-name-error"
            placeholder="Jordan Lee"
          >
          <p class="error-text" id="full-name-error" aria-live="polite"></p>
        </div>

        <div class="form-field">
          <label for="email">Email address <span class="required" aria-hidden="true">*</span></label>
          <input
            id="email"
            name="email"
            type="email"
            autocomplete="email"
            required
            aria-required="true"
            aria-describedby="email-error"
            placeholder="jordan@example.com"
          >
          <p class="error-text" id="email-error" aria-live="polite"></p>
        </div>

        <div class="form-field">
          <label for="phone">Phone number</label>
          <input
            id="phone"
            name="phone"
            type="tel"
            autocomplete="tel"
            inputmode="tel"
            aria-describedby="phone-helper phone-error"
            placeholder="+1 555-123-4567"
          >
          <p class="helper-text" id="phone-helper">Optional. Use digits and include spaces, dashes, or parentheses as needed, for example +1 555-123-4567.</p>
          <p class="error-text" id="phone-error" aria-live="polite"></p>
        </div>

        <button type="submit">Submit request</button>
        <p class="status-text" id="form-status" aria-live="polite"></p>
      </form>
    </section>
  </main>

  <script>
    const form = document.getElementById('support-form');
    const status = document.getElementById('form-status');

    const fields = {
      fullName: {
        input: document.getElementById('full-name'),
        error: document.getElementById('full-name-error'),
        validate(value) {
          if (!value.trim()) {
            return 'Full name is required.';
          }

          if (value.trim().length < 2) {
            return 'Enter your full name.';
          }

          return '';
        }
      },
      email: {
        input: document.getElementById('email'),
        error: document.getElementById('email-error'),
        validate(value) {
          if (!value.trim()) {
            return 'Email address is required.';
          }

          const emailPattern = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
          if (!emailPattern.test(value.trim())) {
            return 'Enter a valid email address.';
          }

          return '';
        }
      },
      phone: {
        input: document.getElementById('phone'),
        error: document.getElementById('phone-error'),
        validate(value) {
          const trimmed = value.trim();
          if (!trimmed) {
            return '';
          }

          const phonePattern = /^\+?[0-9\s().-]{7,20}$/;
          if (!phonePattern.test(trimmed)) {
            return 'Enter a valid phone number using digits and common separators.';
          }

          return '';
        }
      }
    };

    function showError(field, message) {
      field.error.textContent = message;
      field.input.setAttribute('aria-invalid', message ? 'true' : 'false');
